using MediatR; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using VetCommission.Application.Features.ProfessionalRoles; using VetCommission.WebApi.Auth; using VetCommission.WebApi.Extensions;
namespace VetCommission.WebApi.Controllers;
[ApiController,Route("api/funcoes-cargos"),Authorize(Policy=AuthorizationPolicyNames.ProfessionalRolesManage)] public sealed class ProfessionalRolesController(IMediator mediator):ControllerBase
{ [HttpGet] public async Task<IActionResult> List([FromQuery] int page=1,[FromQuery] int pageSize=20,CancellationToken c=default)=>(await mediator.Send(new ListProfessionalRolesQuery(page,pageSize),c)).ToActionResult(this); [HttpPost] public async Task<IActionResult> Save(SaveProfessionalRoleCommand command,CancellationToken c)=>(await mediator.Send(command,c)).ToActionResult(this); [HttpPut("{id:guid}")] public async Task<IActionResult> Update(Guid id, SaveProfessionalRoleRequest request,CancellationToken c)=>(await mediator.Send(new SaveProfessionalRoleCommand(id,request.Name),c)).ToActionResult(this); [HttpPost("{id:guid}/ativar")] public async Task<IActionResult> Activate(Guid id,CancellationToken c)=>(await mediator.Send(new SetProfessionalRoleActiveCommand(id,true),c)).ToActionResult(this); [HttpPost("{id:guid}/inativar")] public async Task<IActionResult> Deactivate(Guid id,CancellationToken c)=>(await mediator.Send(new SetProfessionalRoleActiveCommand(id,false),c)).ToActionResult(this); public sealed record SaveProfessionalRoleRequest(string Name); }
